/**
 * 创建独立的方法
 *
 * 注意：动画由 requestAnimationFrame 驱动，浏览器会暂停隐藏标签页的
 * requestAnimationFrame，因此标签页切到后台时滚动会停在当前位置、结束回调也不会触发，
 * 等重新可见后从暂停处继续。若需要立即到位，请直接用 ele.scrollTo(0, top)。
 *
 * @returns 平滑滚动方法
 */
export declare const createSmoothScroll: () => (ele: HTMLElement, top: number, cb?: () => void, timeout?: number | boolean) => void;
/**
 * 平滑滚动
 *
 * 注意：标签页切到后台时 requestAnimationFrame 被浏览器暂停，滚动与结束回调都会推迟到
 * 重新可见后继续，详见 createSmoothScroll。
 *
 * @param ele 滚动容器
 * @param top 目标位置
 * @param cb 执行完成时的回执事件
 * @param timeout 延迟执行回执事件毫秒值，false不延迟
 */
export declare const smoothScroll: (ele: HTMLElement, top: number, cb?: () => void, timeout?: number | boolean) => void;
